CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(3121,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','mark',15,34,$n$The Markan-parallel — *Eloi, Eloi, lama sabachthani*.$n$,$n$Mark 15:34 — *And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why hast thou forsaken me?* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) Mark gives the same cry at the same hour, with *Eloi, Eloi* spelled his way and the meaning set right beside it. Two witnesses wrote it down alike. What he cried is the first line of David's psalm, and both accounts keep it whole.$n$,6,$n$The Markan-parallel — *Eloi, Eloi, lama sabachthani*.$n$,$n$Mark 15:34 — *Eloi, Eloi, lama sabachthani? which is, being interpreted.* Mark carries the same cry and gives its meaning, so the opening line of the psalm stands in both accounts.$n$),
(3126,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','hebrews',2,11,$n$*He is not ashamed to call them brethren* + Tehillim 22:22 citation.$n$,$n$Hebrews 2:11 — *For both he that sanctifieth and they who are sanctified are all of one: for which cause he is not ashamed to call them brethren,* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) He cries out as one forsaken, and Hebrews says he is *not ashamed* to call the sanctified his brethren. The one who sanctifies and those sanctified are *all of one*. The psalm he opens with turns to his brethren, and they are kin, the seed of the fathers.$n$,6,$n$*He is not ashamed to call them brethren* + Tehillim 22:22 citation.$n$,$n$Hebrews 2:11 — *for which cause he is not ashamed to call them brethren.* He is not ashamed to call them brethren because he and they are all of one, the kin the psalm says he declares the name to.$n$),
(3127,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','hebrews',5,7,$n$*Offered up prayers and supplications.*$n$,$n$Hebrews 5:7 — *Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears unto him that was able to save him from death, and was heard in that he feared;* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) The loud cry at the ninth hour is what Hebrews calls *strong crying and tears*. It was a prayer to the one *able to save him from death*, and he *was heard*. So the cry is not despair. It is a man praying in the days of his flesh.$n$,6,$n$*Offered up prayers and supplications.*$n$,$n$Hebrews 5:7 — *when he had offered up prayers and supplications with strong crying and tears.* The strong crying and tears are the loud cry at the ninth hour, a prayer offered to the one who heard him.$n$),
(3128,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','john',16,32,$n$*Yet I am not alone, because the Father is with me.*$n$,$n$John 16:32 — *Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me.* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) The night before, he told them they would scatter and leave him alone, and he said he was not alone, because the Father was with him. So the cry is the first line of David's psalm and not a son cut off from his Father. The Father who stood with him in the upper room is the one he calls on at the ninth hour.$n$,6,$n$*Yet I am not alone, because the Father is with me.*$n$,$n$John 16:32 — *and yet I am not alone, because the Father is with me.* He says the night before that he is not alone because the Father is with him, so the cry is the psalm's opening and not abandonment.$n$),
(3129,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','john',17,5,$n$*Glorify thou me with thine own self.*$n$,$n$John 17:5 — *And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was.* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) Hours before the cross he asks the Father for *the glory which I had with thee*. He speaks as one who was with the Father before the world was, and who goes back to him. The cry at the ninth hour is that same man calling on his Elohim (God), not a stranger to him.$n$,6,$n$*Glorify thou me with thine own self.*$n$,$n$John 17:5 — *glorify thou me with thine own self with the glory which I had with thee.* He asks to be glorified with the Father's own self, the glory he had before the world, so the cry comes from one who is the Father's own.$n$),
(3130,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','2-corinthians',5,21,$n$*He hath made him to be sin for us, who knew no sin.*$n$,$n$2 Corinthians 5:21 — *For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of Elohim (God) in him.* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) The one who knew no sin was made sin for us, and that is why a sinless man cries out as forsaken. Paul says it plainly where the psalm says it in its first line. And the psalm does not stop there: it ends with his righteousness declared to a people born.$n$,6,$n$*He hath made him to be sin for us, who knew no sin.*$n$,$n$2 Corinthians 5:21 — *he hath made him to be sin for us, who knew no sin.* Made sin for us though he knew no sin is why the sinless man cries out as one forsaken.$n$),
(3131,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','galatians',3,13,$n$*Made a curse for us* — Devarim 21:22-23 substance.$n$,$n$Galatians 3:13 — *Messiah (Christ) hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) He hung on the tree, and the writing says *Cursed is every one that hangeth on a tree*. That is the weight under the cry, a man hanging where the curse falls. He took the curse that the law names, and the law itself stands. The psalm that opens with his forsaking ends with a people born.$n$,6,$n$*Made a curse for us* — Devarim 21:22-23 substance.$n$,$n$Galatians 3:13 — *hath redeemed us from the curse of the law, being made a curse for us.* He took the curse the law names by hanging on the tree, which is the weight under the cry at the ninth hour.$n$),
(3132,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','1-peter',2,24,$n$*Bare our sins in his own body on the tree.*$n$,$n$1 Peter 2:24 — *Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) Peter says he *bare our sins* in his own body on the tree, and that by his stripes *ye were healed*. That is what hangs behind the cry at the ninth hour. It was not abandonment for nothing. The psalm turns, and those who were healed are the brethren he declares the name to.$n$,6,$n$*Bare our sins in his own body on the tree.*$n$,$n$1 Peter 2:24 — *Who his own self bare our sins in his own body on the tree.* He bore sins in his own body on the tree, the weight behind the cry, and by his stripes his people were healed.$n$),
(3133,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','psalms',31,5,$n$*Into thine hand I commit my spirit* — the substantial-Lukan-cross-cry-substance.$n$,$n$Psalm 31:5 — *Into thine hand I commit my spirit: thou hast redeemed me, O Yahuah Elohim (LORD God) of truth.* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) His last words are another psalm of David. He opened with the first line of Psalm 22, and he ended by giving his spirit into the Father's hand: *Into thine hand I commit my spirit*. A man abandoned does not hand his spirit over. He was held the whole time, and *thou hast redeemed me* is how he goes.$n$,6,$n$*Into thine hand I commit my spirit* — the substantial-Lukan-cross-cry-substance.$n$,$n$Psalm 31:5 — *Into thine hand I commit my spirit: thou hast redeemed me.* His last words are David's, committing his spirit into the Father's hand, so the cry is a man held and not a man left.$n$),
(3134,'canon','matthew',27,46,$n$And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','psalms',69,21,$n$The vinegar-substance — the substantial-second-Tehillim-citation-at-the-Cross.$n$,$n$Psalm 69:21 — *They gave me also gall for my meat; and in my thirst they gave me vinegar to drink.* *And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why have you forsaken me?* (Matthew 27:46) The same afternoon fits another psalm of David. His *thirst* is met with *gall* and *vinegar to drink*. The man who named the opening line of one psalm has the other in his mouth too, and the day walks through them line by line.$n$,6,$n$The vinegar-substance — the substantial-second-Tehillim-citation-at-the-Cross.$n$,$n$Psalm 69:21 — *in my thirst they gave me vinegar to drink.* The gall and the vinegar given in his thirst are David's words, one more line of the psalms the afternoon walks through.$n$),
(5346,'canon','mark',15,34,$n$And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','psalms',22,1,$n$thread:eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance | *Eloi, Eloi, lama sabachthani* — Tehillim (Psalm) 22:1 cited as the opening of the whole psalm. The cry is not despair; it is the citation of the psalm whose ending is the vindication.$n$,$n$Psalm 22:1 — *My Elohim (God), my Elohim (God), why hast thou forsaken me? why art thou so far from helping me, and from the words of my roaring?* *And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?* (Mark 15:34) Mark gives the cry in his own tongue and then the meaning, and the meaning is David's first line. A man who says the opening has the whole psalm in his mouth. It is not despair. The psalm goes on past the forsaking, to praise and a name declared.$n$,6,$n$*Eloi, Eloi, lama sabachthani* — Tehillim (Psalm) 22:1 cited as the opening of the whole psalm. The cry is not despair; it is the citation of the psalm whose ending is the vindication.$n$,$n$Psalm 22:1 — *My Elohim (God), my Elohim (God), why hast thou forsaken me?* David's first line is the cry word for word, so the whole psalm that follows is what he is naming.$n$),
(5347,'canon','mark',15,34,$n$And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','psalms',22,24,$n$thread:eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance | Tehillim (Psalm) 22:24 — the vindication-arc the citation invokes.$n$,$n$Psalm 22:24 — *For he hath not despised nor abhorred the affliction of the afflicted; neither hath he hid his face from him; but when he cried unto him, he heard.* *And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?* (Mark 15:34) He cried with a loud voice at the ninth hour. The psalm he named says what became of a cry like that: *neither hath he hid his face from him*. The forsaking is where the psalm begins, and the hearing is where it turns.$n$,6,$n$Tehillim (Psalm) 22:24 — the vindication-arc the citation invokes.$n$,$n$Psalm 22:24 — *neither hath he hid his face from him; but when he cried unto him, he heard.* The afflicted one's cry is heard and his face is not hidden, which is the turn the opening line leads to.$n$),
(5348,'canon','mark',15,34,$n$And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','psalms',22,27,$n$thread:eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance | *All the ends of the world shall remember and turn unto Yahuah (the LORD)* (Tehillim/Psalm 22:27).$n$,$n$Psalm 22:27 — *All the ends of the world shall remember and turn unto Yahuah (LORD): and all the kindreds of the nations shall worship before thee.* *And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?* (Mark 15:34) The psalm reaches past the cross to the ends of the world, and the word is *remember*. A people remembers what it once knew, so those who turn are not strangers hearing of him for the first time. The nations are named beside them, and they *shall worship before thee*.$n$,6,$n$*All the ends of the world shall remember and turn unto Yahuah (the LORD)* (Tehillim/Psalm 22:27).$n$,$n$Psalm 22:27 — *All the ends of the world shall remember and turn unto Yahuah (LORD).* The ends of the world remember and turn, as a people does who once knew him, and the nations worship beside them.$n$),
(5349,'canon','mark',15,34,$n$And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?$n$,'canon','psalms',22,31,$n$thread:eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance | *They shall come, and shall declare his righteousness unto a people that shall be born* (Tehillim/Psalm 22:31).$n$,$n$Psalm 22:31 — *They shall come, and shall declare his righteousness unto a people that shall be born, that he hath done this.* *And at the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My Elohim (God), my Elohim (God), why have you forsaken me?* (Mark 15:34) The psalm ends with a people yet to be born hearing *he hath done this*. The man who opened with the forsaking is the one whose work is declared at the end. That is why the cry at the ninth hour is not the last word. The rest of the afternoon walks to this line.$n$,6,$n$*They shall come, and shall declare his righteousness unto a people that shall be born* (Tehillim/Psalm 22:31).$n$,$n$Psalm 22:31 — *They shall come, and shall declare his righteousness unto a people that shall be born.* The psalm ends with his righteousness declared to a people yet to be born, which is where the opening cry was always headed.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (6, 'eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance', $n$Eli, Eli, lama sabachthani — the first line of Psalm 22, and the whole psalm behind it (Hebrews 2; Psalm 31)$n$, $n$Eli, Eli, lama sabachthani — the first line of Psalm 22, and the whole psalm behind it (Hebrews 2; Psalm 31)$n$, $n$It ain't new. At the ninth hour he cries out in the words of David:

*And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why hast thou forsaken me?* (Matthew 27:46)

*My Elohim (God), my Elohim (God), why hast thou forsaken me? why art thou so far from helping me, and from the words of my roaring?* (Psalm 22:1)

A man who names the first line of a psalm has the whole psalm in his mouth, and the psalm does not end in the forsaking. It turns, and the one who was forsaken speaks of his brethren:

*I will declare thy name unto my brethren: in the midst of the congregation will I praise thee.* (Psalm 22:22)

The letter to the Hebrews puts that verse in his mouth and tells who the brethren are:

*For both he that sanctifieth and they who are sanctified are all of one: for which cause he is not ashamed to call them brethren,* (Hebrews 2:11)

*Saying, I will declare thy name unto my brethren, in the midst of the church will I sing praise unto thee.* (Hebrews 2:12)

*All of one*: the brethren are kin, the seed of the fathers he took flesh among. The psalm then reaches past the congregation to the ends of the world, and the word for what they do is *remember*, which is what a people does who once knew him:

*All the ends of the world shall remember and turn unto Yahuah (LORD): and all the kindreds of the nations shall worship before thee.* (Psalm 22:27)

*They shall come, and shall declare his righteousness unto a people that shall be born, that he hath done this.* (Psalm 22:31)

The cry was not a man losing his Father. He said as much the night before:

*Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me.* (John 16:32)

And his last words were another psalm of David, the hand he committed his spirit into being the Father's:

*Into thine hand I commit my spirit: thou hast redeemed me, O Yahuah Elohim (LORD God) of truth.* (Psalm 31:5)

*And when Yahusha (Jesus) had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost.* (Luke 23:46)

Why hast thou forsaken me is the first line of a psalm that ends with a people born and a righteousness declared. He quoted the whole of it by its opening, and the rest of the afternoon walked through it line by line.$n$, $n$It ain't new. At the ninth hour he cries out in the words of David:

*And about the ninth hour Yahusha (Jesus) cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My Elohim (God), my Elohim (God), why hast thou forsaken me?* (Matthew 27:46)

*My Elohim (God), my Elohim (God), why hast thou forsaken me? why art thou so far from helping me, and from the words of my roaring?* (Psalm 22:1)

A man who names the first line of a psalm has the whole psalm in his mouth, and the psalm does not end in the forsaking. It turns, and the one who was forsaken speaks of his brethren:

*I will declare thy name unto my brethren: in the midst of the congregation will I praise thee.* (Psalm 22:22)

The letter to the Hebrews puts that verse in his mouth and tells who the brethren are:

*For both he that sanctifieth and they who are sanctified are all of one: for which cause he is not ashamed to call them brethren,* (Hebrews 2:11)

*Saying, I will declare thy name unto my brethren, in the midst of the church will I sing praise unto thee.* (Hebrews 2:12)

*All of one*: the brethren are kin, the seed of the fathers he took flesh among. The psalm then reaches past the congregation to the ends of the world, and the word for what they do is *remember*, which is what a people does who once knew him:

*All the ends of the world shall remember and turn unto Yahuah (LORD): and all the kindreds of the nations shall worship before thee.* (Psalm 22:27)

*They shall come, and shall declare his righteousness unto a people that shall be born, that he hath done this.* (Psalm 22:31)

The cry was not a man losing his Father. He said as much the night before:

*Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me.* (John 16:32)

And his last words were another psalm of David, the hand he committed his spirit into being the Father's:

*Into thine hand I commit my spirit: thou hast redeemed me, O Yahuah Elohim (LORD God) of truth.* (Psalm 31:5)

*And when Yahusha (Jesus) had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost.* (Luke 23:46)

Why hast thou forsaken me is the first line of a psalm that ends with a people born and a righteousness declared. He quoted the whole of it by its opening, and the rest of the afternoon walked through it line by line.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 6 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 6 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (eli-eli-lama-sabachthani) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — eli-eli-lama-sabachthani done.'
